    a = [row[:pw] for row in a[:ph]]
    b = [row[:pw] for row in b[:ph]]
    background = Counter(v for row in a for v in row).most_common(1)[0][0]
    return [[3 if a[r][c] == b[r][c] else background for c in range(pw)]
            for r in range(ph)]


